// --- Attachment / image handling -------------------------------------------
// Supabase Storage is replaced by base64-in-database storage: uploaded files
// are inlined as data URLs (single-user personal deployment, no object store).

const fileToBase64 = (file: Blob): Promise<string> =>
  new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result as string);
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });

const processRAFile = async (fi: RAFile): Promise<RAFile> => {
  if (fi?.rawFile instanceof File) {
    const src = await fileToBase64(fi.rawFile);
    return { ...fi, src, type: fi.rawFile.type };
  }
  return fi;
};

const processConfigLogo = async (logo: any): Promise<string> => {
  if (typeof logo === "string") return logo;
  if (logo?.rawFile instanceof File) {
    return await fileToBase64(logo.rawFile);
  }
  return logo?.src ?? "";
};

const processCompanyLogo = async (params: any) => {
  const logo = params.data.logo;
  if (logo?.rawFile instanceof File) {
    const src = await fileToBase64(logo.rawFile);
    return {
      ...params,
      data: {
        ...params.data,
        logo: { src, title: logo.title, type: logo.rawFile.type },
      },
    };
  }
  return params;
};

// --- Data provider ----------------------------------------------------------

const getDataProviderWithCustomMethods = () => {
  return {
    ...baseDataProvider,
    async getList(resource: string, params: GetListParams) {
      if (resource === "companies") {
        return baseDataProvider.getList("companies_summary", params);
      }
      if (resource === "contacts") {
        return baseDataProvider.getList("contacts_summary", params);
      }
      if (resource === "activity_log") {
        const { filter = {}, pagination } = params;
        const all = await getActivityLog(
          baseDataProvider,
          filter.company_id,
          filter.sales_id,
        );
        const { page = 1, perPage = 25 } = pagination ?? {};
        const start = (page - 1) * perPage;
        return {
          data: all.slice(start, start + perPage) as any[],
          total: all.length,
        };
      }
      return baseDataProvider.getList(resource, params);
    },
    async getOne(resource: string, params: any) {
      if (resource === "companies") {
        return baseDataProvider.getOne("companies_summary", params);
      }
      if (resource === "contacts") {
        return baseDataProvider.getOne("contacts_summary", params);
      }
      return baseDataProvider.getOne(resource, params);
    },

    async signUp({ email, password, first_name, last_name }: SignUpData) {
      const initialized = await getIsInitialized();
      const { data: sale } = await baseDataProvider.create<Sale>("sales", {
        data: {
          email,
          first_name,
          last_name,
          administrator: !initialized, // the first user is the administrator
          disabled: false,
          user_id: crypto.randomUUID(),
        } as Partial<Sale>,
      });
      cacheCurrentSale(sale);
      return { id: sale.id, email, password };
    },
    async salesCreate(body: SalesFormData) {
      const avatar = body.avatar
        ? await processRAFile(
            typeof body.avatar === "string"
              ? ({ src: body.avatar } as RAFile)
              : (body.avatar as RAFile),
          )
        : undefined;
      const { data } = await baseDataProvider.create<Sale>("sales", {
        data: {
          email: body.email,
          first_name: body.first_name,
          last_name: body.last_name,
          administrator: body.administrator ?? false,
          disabled: body.disabled ?? false,
          avatar,
          user_id: crypto.randomUUID(),
        } as Partial<Sale>,
      });
      return data;
    },
    async salesUpdate(
      id: Identifier,
      data: Partial<Omit<SalesFormData, "password">>,
    ) {
      const { avatar, ...rest } = data as any;
      const patch: Record<string, unknown> = { ...rest };
      if (avatar) {
        patch.avatar = await processRAFile(
          typeof avatar === "string" ? ({ src: avatar } as RAFile) : avatar,
        );
      }
      const { data: updated } = await baseDataProvider.update<Sale>("sales", {
        id,
        data: patch,
        previousData: { id } as Sale,
      });
      return updated;
    },
    async updatePassword(_id: Identifier) {
      // No real authentication in this deployment: nothing to reset.
      return true;
    },
    async unarchiveDeal(deal: Deal) {
      const { data: deals } = await baseDataProvider.getList<Deal>("deals", {
        filter: { stage: deal.stage },
        pagination: { page: 1, perPage: 1000 },
        sort: { field: "index", order: "ASC" },
      });

      const updatedDeals = deals.map((d, index) => ({
        ...d,
        index: d.id === deal.id ? 0 : index + 1,
        archived_at: d.id === deal.id ? null : d.archived_at,
      }));

      return await Promise.all(
        updatedDeals.map((updatedDeal) =>
          baseDataProvider.update("deals", {
            id: updatedDeal.id,
            data: updatedDeal,
            previousData: deals.find((d) => d.id === updatedDeal.id),
          }),
        ),
      );
    },
    async isInitialized() {
      return getIsInitialized();
    },
    async mergeContacts(sourceId: Identifier, targetId: Identifier) {
      return mergeContactsCommon(sourceId, targetId, baseDataProvider);
    },
    async getConfiguration(): Promise<ConfigurationContextValue> {
      const { data } = await baseDataProvider.getOne("configuration", {
        id: 1,
      });
      return (data?.config as ConfigurationContextValue) ?? {};
    },
    async updateConfiguration(
      config: ConfigurationContextValue,
    ): Promise<ConfigurationContextValue> {
      const { data } = await baseDataProvider.update("configuration", {
        id: 1,
        data: { config },
        previousData: { id: 1 },
      });
      return data.config as ConfigurationContextValue;
    },
  } satisfies DataProvider;
};

export type CrmDataProvider = ReturnType<
  typeof getDataProviderWithCustomMethods
>;

const lifeCycleCallbacks: ResourceCallbacks[] = [
  {
    resource: "configuration",
    beforeUpdate: async (params) => {
      const config = params.data.config;
      if (config) {
        config.lightModeLogo = await processConfigLogo(config.lightModeLogo);
        config.darkModeLogo = await processConfigLogo(config.darkModeLogo);
      }
      return params;
    },
  },
  {
    resource: "contact_notes",
    beforeSave: async (data: ContactNote, _, __) => {
      if (data.attachments) {
        data.attachments = await Promise.all(
          data.attachments.map((fi) => processRAFile(fi)),
        );
      }
      return data;
    },
  },
  {
    resource: "deal_notes",
    beforeSave: async (data: DealNote, _, __) => {
      if (data.attachments) {
        data.attachments = await Promise.all(
          data.attachments.map((fi) => processRAFile(fi)),
        );
      }
      return data;
    },
  },
  {
    resource: "sales",
    beforeSave: async (data: Sale, _, __) => {
      if (data.avatar) {
        data.avatar = await processRAFile(data.avatar as RAFile);
      }
      return data;
    },
  },
  {
    resource: "contacts",
    beforeGetList: async (params) => {
      return applyFullTextSearch([
        "first_name",
        "last_name",
        "company_name",
        "title",
        "email",
        "phone",
        "background",
      ])(params);
    },
  },
  {
    resource: "companies",
    beforeGetList: async (params) => {
      return applyFullTextSearch([
        "name",
        "phone_number",
        "website",
        "zipcode",
        "city",
        "state_abbr",
      ])(params);
    },
    beforeCreate: async (params) => {
      const createParams = await processCompanyLogo(params);
      return {
        ...createParams,
        data: {
          created_at: new Date().toISOString(),
          ...createParams.data,
        },
      };
    },
    beforeUpdate: async (params) => {
      return await processCompanyLogo(params);
    },
  },
  {
    resource: "contacts_summary",
    beforeGetList: async (params) => {
      return applyFullTextSearch(["first_name", "last_name"])(params);
    },
  },
  {
    resource: "deals",
    beforeGetList: async (params) => {
      return applyFullTextSearch(["name", "category", "description"])(params);
    },
  },
];

export const getDataProvider = (): CrmDataProvider => {
  return withLifecycleCallbacks(
    getDataProviderWithCustomMethods(),
    lifeCycleCallbacks,
  ) as CrmDataProvider;
};

const applyFullTextSearch = (columns: string[]) => (params: GetListParams) => {
  if (!params.filter?.q) {
    return params;
  }
  const { q, ...filter } = params.filter;
  return {
    ...params,
    filter: {
      ...filter,
      "@or": columns.reduce((acc, column) => {
        if (column === "email")
          return {
            ...acc,
            [`email_fts@ilike`]: q,
          };
        if (column === "phone")
          return {
            ...acc,
            [`phone_fts@ilike`]: q,
          };
        else
          return {
            ...acc,
            [`${column}@ilike`]: q,
          };
      }, {}),
    },
  };
};

import type { AuthProvider } from "ra-core";

import type { Sale } from "../../types";
import { canAccess } from "../commons/canAccess";
import { baseDataProvider } from "./internal/httpClient";

const PASSWORD = "bite";
const BLOCK_DURATION = 60 * 60 * 1000;
const MAX_ATTEMPTS = 3;
const AUTH_KEY = "app_auth";
const ATTEMPTS_KEY = "app_login_attempts";

interface LoginAttempts {
  count: number;
  blockedUntil: number | null;
}

function getAttempts(): LoginAttempts {
  if (typeof window === "undefined") return { count: 0, blockedUntil: null };
  const raw = localStorage.getItem(ATTEMPTS_KEY);
  if (!raw) return { count: 0, blockedUntil: null };
  try {
    return JSON.parse(raw);
  } catch {
    return { count: 0, blockedUntil: null };
  }
}

function setAttempts(data: LoginAttempts) {
  if (typeof window !== "undefined") {
    localStorage.setItem(ATTEMPTS_KEY, JSON.stringify(data));
  }
}

function isAuthenticated(): boolean {
  if (typeof window === "undefined") return false;
  return localStorage.getItem(AUTH_KEY) === "1";
}

export function getIsInitialized(): Promise<boolean> {
  return Promise.resolve(true);
}

export function cacheCurrentSale(_sale: any) {
  // no-op since we removed sign-up flow
}

// --- Identity resolution -----------------------------------------------------
// This is a single-user, no-login deployment (see the shared-password gate
// below): there is no real authentication, but every write (notes, contacts,
// deals, tasks) still stamps `sales_id`, an INTEGER FK to `sales.id`. We treat
// the first `sales` row (by id) as "the" user, and self-provision a default
// one the first time the table is empty — the removed `/sign-up` onboarding
// used to create it.

async function fetchFirstSale(): Promise<Sale | null> {
  const { data } = await baseDataProvider.getList<Sale>("sales", {
    filter: {},
    pagination: { page: 1, perPage: 1 },
    sort: { field: "id", order: "ASC" },
  });
  return data[0] ?? null;
}

/**
 * Creates the default sales row the first time the table is empty.
 * Race-safe: `sales.email` is UNIQUE, so if a concurrent caller (another tab,
 * or a simultaneous request) already created the row, the insert fails and we
 * re-fetch the row it created instead of throwing.
 */
async function provisionDefaultSale(): Promise<Sale> {
  try {
    const { data } = await baseDataProvider.create<Sale>("sales", {
      data: {
        first_name: "Admin",
        last_name: "User",
        email: "admin@local",
        administrator: true,
        disabled: false,
        user_id: crypto.randomUUID(),
      } as Partial<Sale>,
    });
    return data;
  } catch (error) {
    const existing = await fetchFirstSale();
    if (existing) return existing;
    throw error;
  }
}

/** Resolves the current user: the first `sales` row, self-provisioned if none exists yet. */
async function getCurrentSale(): Promise<Sale> {
  const existing = await fetchFirstSale();
  if (existing) return existing;
  return provisionDefaultSale();
}

export const getAuthProvider = (): AuthProvider => ({
  login: async ({ password }: { password?: string }) => {
    const attempts = getAttempts();

    if (attempts.blockedUntil && Date.now() < attempts.blockedUntil) {
      const remaining = Math.ceil((attempts.blockedUntil - Date.now()) / 60000);
      throw new Error(
        `Trop de tentatives. Réessayez dans ${remaining} minute${remaining > 1 ? "s" : ""}.`,
      );
    }

    if (password !== PASSWORD) {
      const newCount = attempts.count + 1;
      if (newCount >= MAX_ATTEMPTS) {
        setAttempts({
          count: newCount,
          blockedUntil: Date.now() + BLOCK_DURATION,
        });
        throw new Error(
          "3 tentatives échouées. Compte bloqué pendant 1 heure.",
        );
      }
      setAttempts({ count: newCount, blockedUntil: null });
      throw new Error("Mot de passe incorrect.");
    }

    setAttempts({ count: 0, blockedUntil: null });
    if (typeof window !== "undefined") {
      localStorage.setItem(AUTH_KEY, "1");
    }
    return undefined;
  },
  logout: async () => {
    if (typeof window !== "undefined") {
      localStorage.removeItem(AUTH_KEY);
    }
    return undefined;
  },
  checkError: async () => undefined,
  checkAuth: async () => {
    if (!isAuthenticated()) {
      throw new Error("Not authenticated");
    }
  },
  canAccess: async (params: any) => {
    return canAccess("admin", params as any);
  },
  getIdentity: async () => {
    const sale = await getCurrentSale();
    return {
      id: sale.id,
      fullName: `${sale.first_name} ${sale.last_name}`,
      avatar: sale.avatar?.src,
    };
  },
});

import { HttpError, type DataProvider } from "ra-core";

/**
 * Low-level data provider that talks to the Atomic CRM backend
 * (server/index.mjs) over HTTP. Each method POSTs to
 * `${API_URL}/:resource/:method` with a JSON body matching the react-admin
 * DataProvider params, and the backend returns the matching react-admin shape.
 *
 * The backend understands the app's PostgREST-style `field@operator` filters
 * directly, so filters are forwarded unchanged.
 */
const API_URL = import.meta.env.VITE_API_URL ?? "/api";

async function apiFetch<T = any>(
  resource: string,
  method: string,
  body: Record<string, unknown>,
): Promise<T> {
  const response = await fetch(`${API_URL}/${resource}/${method}`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(body),
  });

  const json = await response.json().catch(() => ({}));
  if (!response.ok) {
    throw new HttpError(
      json?.error ?? response.statusText,
      response.status,
      json,
    );
  }
  return json as T;
}

export const baseDataProvider: DataProvider = {
  getList: (resource, params) =>
    apiFetch(resource, "getList", {
      filter: params.filter,
      sort: params.sort,
      pagination: params.pagination,
    }),
  getOne: (resource, params) => apiFetch(resource, "getOne", { id: params.id }),
  getMany: (resource, params) =>
    apiFetch(resource, "getMany", { ids: params.ids }),
  getManyReference: (resource, params) =>
    apiFetch(resource, "getManyReference", {
      target: params.target,
      id: params.id,
      filter: params.filter,
      sort: params.sort,
      pagination: params.pagination,
    }),
  create: (resource, params) =>
    apiFetch(resource, "create", { data: params.data }),
  update: (resource, params) =>
    apiFetch(resource, "update", { id: params.id, data: params.data }),
  updateMany: (resource, params) =>
    apiFetch(resource, "updateMany", { ids: params.ids, data: params.data }),
  delete: (resource, params) => apiFetch(resource, "delete", { id: params.id }),
  deleteMany: (resource, params) =>
    apiFetch(resource, "deleteMany", { ids: params.ids }),
};

